<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientRequirePushedAuthorizationRequestsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRequirePushedAuthorizationRequestsAccessor trait.
 *
 * Covers null default, string/VO assignment via withRequirePushedAuthorizationRequests,
 * getRequirePushedAuthorizationRequests/requirePushedAuthorizationRequests accessors, and isRequirePushedAuthorizationRequestsChanged with/without original.
 */
class TrustedClientRequirePushedAuthorizationRequestsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRequirePushedAuthorizationRequests creates a new instance with the RequirePushedAuthorizationRequests set
     * from a string value, and getRequirePushedAuthorizationRequests returns the primitive string.
     */
    public function testWithRequirePushedAuthorizationRequestsFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePushedAuthorizationRequestsAccessorUnitTest();

        // Act
        $result = $holder->withRequirePushedAuthorizationRequests(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isRequirePushedAuthorizationRequests());
    }
    /**
     * Asserts that withrequirePushedAuthorizationRequests has access to the value object
     * from a string value, and getRequirePushedAuthorizationRequests returns the primitive string.
     */
    public function testWithRequirePushedAuthorizationRequestsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePushedAuthorizationRequestsAccessorUnitTest();

        // Act
        $result = $holder->withRequirePushedAuthorizationRequests(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->requirePushedAuthorizationRequests()->value());
    }
    public function testChangedRequirePushedAuthorizationRequests(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequirePushedAuthorizationRequestsAccessorUnitTest()->withRequirePushedAuthorizationRequests(true);
        $original = $holder->withRequirePushedAuthorizationRequests(true);
        $same = $holder->withRequirePushedAuthorizationRequests(true);
        $modified = $holder->withRequirePushedAuthorizationRequests(false);

        // Act
        $withSame = $original->isRequirePushedAuthorizationRequestsChanged($same);
        $withDiferent = $original->isRequirePushedAuthorizationRequestsChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientRequirePushedAuthorizationRequestsAccessorUnitTest
{
    use TrustedClientRequirePushedAuthorizationRequestsAccessor;
}
